#include <iostream>
#include <ranges>

namespace stq {
void println(auto, const auto &v) {
    for (const auto &e : v)
        std::cout << e << ' ';
    std::cout << '\n';
}
} // namespace stq

int main() {
    static constexpr int a[]{1, 2, 3, 4, 5};
    constexpr auto view = a | std::views::drop(2);
    stq::println("{}", view);
    const auto base = view.base();
    stq::println("{}", base);
}
